36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.server.ResponseStatusException;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
103	        HttpHeaders headers = new HttpHeaders();
104	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
105	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
106	        owner.setTelephone(normalizedTelephone);
107	        owner.setEmail(normalizeEmail(owner.getEmail()));
108	        if (owner.getRegistrationDate() == null) {
109	            owner.setRegistrationDate(java.time.LocalDate.now());
110	        }
111	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
112	            .map(Owner::getTelephone)
113	            .filter(java.util.Objects::nonNull)
114	            .anyMatch(normalizedTelephone::equals);
115	        if (telephoneInUse) {
116	            throw new ResponseStatusException(HttpStatus.CONFLICT,
117	                "An owner with this telephone number already exists");
118	        }
119	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
120	            String lastNameKey = normalizeForHousehold(owner.getLastName());
121	            String addressKey = normalizeForHousehold(owner.getAddress());
122	            boolean householdInUse = this.clinicService.findAllOwners().stream()
123	                .anyMatch(existing -> normalizeForHousehold(existing.getLastName()).equals(lastNameKey)
124	                    && normalizeForHousehold(existing.getAddress()).equals(addressKey));
125	            if (householdInUse) {
126	                throw new ResponseStatusException(HttpStatus.CONFLICT,
127	                    "An owner with this last name already exists at this address");
128	            }
129	        }
130	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
131	        this.clinicService.saveOwner(owner);
132	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
133	        headers.setLocation(UriComponentsBuilder.newInstance()
134	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
135	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
136	    }
137	
138	    /**
139	     * Builds the customer code for a new owner, formatted {@code '<LAST3>-<NNNN>'} where
140	     * {@code LAST3} is the upper-cased first three letters of the last name and {@code NNNN}
141	     * is a global 4-digit zero-padded sequence equal to one more than the current number of
142	     * owners (e.g. {@code 'SMI-0007'}).
143	     *
144	     * @param lastName the owner's last name
145	     * @return the assigned customer code
146	     */
147	    private String nextCustomerCode(String lastName) {
148	        String prefix = (lastName == null ? "" : lastName);
149	        prefix = prefix.substring(0, Math.min(3, prefix.length())).toUpperCase(java.util.Locale.ROOT);
150	        long sequence = this.clinicService.findAllOwners().size() + 1L;
151	        return String.format("%s-%04d", prefix, sequence);
152	    }
153	
154	    /**
155	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
156	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
157	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
158	     * empty string.
159	     *
160	     * @param value the raw value (last name or address) as submitted
161	     * @return the normalized comparison key
162	     */
163	    private String normalizeForHousehold(String value) {
164	        if (value == null) {
165	            return "";
166	        }
167	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
168	    }
169	
170	    /**
171	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
172	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
173	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
174	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
175	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
176	     * is stored as {@code '+61412345678'}.
177	     *
178	     * @param telephone the raw telephone number as submitted
179	     * @return the normalized E.164 telephone number
180	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
181	     *         number (8 to 15 digits after the '+')
182	     */
183	    private String normalizeTelephone(String telephone) {
184	        String raw = telephone == null ? "" : telephone.trim();
185	        String digits = raw.replaceAll("\\D", "");
186	        String e164;
187	        if (raw.startsWith("+")) {
188	            e164 = "+" + digits;
189	        } else {
190	            if (digits.startsWith("0")) {
191	                digits = digits.substring(1);
192	            }
193	            e164 = "+61" + digits;
194	        }
195	        int digitCount = e164.length() - 1;
196	        if (digitCount < 8 || digitCount > 15) {
197	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
198	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
199	        }
200	        return e164;
201	    }
202	
203	    /**
204	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
205	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
206	     * (absent) or already valid.
207	     *
208	     * @param email the email address as submitted, or {@code null} when absent
209	     * @return the lower-cased email, or {@code null} when absent
210	     */
211	    private String normalizeEmail(String email) {
212	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
213	    }
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
218	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
219	        if (currentOwner == null) {
220	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
221	        }
222	        currentOwner.setAddress(ownerFieldsDto.getAddress());
223	        currentOwner.setCity(ownerFieldsDto.getCity());
224	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
225	        currentOwner.setLastName(ownerFieldsDto.getLastName());
226	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
227	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
228	        this.clinicService.saveOwner(currentOwner);
229	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
230	    }
231	
232	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
233	    @Transactional
234	    @Override
235	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
236	        Owner owner = this.clinicService.findOwnerById(ownerId);
237	        if (owner == null) {
238	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
239	        }
240	        this.clinicService.deleteOwner(owner);
241	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
242	    }
243	
244	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
245	    @Override
246	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
247	        Owner owner = this.clinicService.findOwnerById(ownerId);
248	        if (owner == null) {
249	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
250	        }
251	        HttpHeaders headers = new HttpHeaders();
252	        Pet pet = petMapper.toPet(petFieldsDto);
253	        owner.setId(ownerId);
254	        pet.setOwner(owner);
255	        pet.getType().setName(null);
256	        this.clinicService.savePet(pet);
257	        PetDto petDto = petMapper.toPetDto(pet);
258	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
259	            .buildAndExpand(pet.getId()).toUri());
260	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
261	    }
262	
263	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
264	    @Override
265	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
266	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
267	        if (currentOwner != null) {
268	            Pet currentPet = this.clinicService.findPetById(petId);
269	            if (currentPet != null) {
270	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
271	                currentPet.setName(petFieldsDto.getName());
272	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
273	                this.clinicService.savePet(currentPet);
274	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
275	            }
276	        }
277	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
278	    }
279	
280	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
281	    @Override
282	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
283	        HttpHeaders headers = new HttpHeaders();
284	        Visit visit = visitMapper.toVisit(visitFieldsDto);
285	        Pet pet = new Pet();
286	        pet.setId(petId);
287	        visit.setPet(pet);
288	        this.clinicService.saveVisit(visit);
289	        VisitDto visitDto = visitMapper.toVisitDto(visit);
290	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
291	            .buildAndExpand(visit.getId()).toUri());
292	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
293	    }
294	
295	
296	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
297	    @Override
298	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
299	        Owner owner = this.clinicService.findOwnerById(ownerId);
300	        if (owner != null) {
301	            Pet pet = owner.getPet(petId);
302	            if (pet != null) {
303	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
304	            }
305	        }
306	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
307	    }
308	}
